qss.cards:
QScrollArea#PluginCardsArea { border: 1px solid ${accent_primary}; border-radius: 10px; background: transparent; }
QFrame#PluginCard { background: ${bg_panel_glass}; border:1px solid ${border_glow}; border-radius:12px; transition: all 180ms ease; font-family:${font_ui}; }
QFrame#PluginCard:hover { border:1px solid ${accent_secondary}; box-shadow:0 0 6px ${accent_primary}; }
QFrame#PluginCard[installed="true"] { border:1px solid ${accent_secondary}; }
QFrame#PluginCard QPushButton[card-install="installed"] { background: #1e293b; color:${accent_secondary}; border:1px solid ${accent_secondary}; }
QFrame#PluginCard QPushButton[card-install="installed"]:disabled { opacity:0.85; }
QFrame#PluginCard QLabel { color:${text_secondary}; }
QFrame#PluginCard QLabel:hover { color:${text_primary}; }
